describe('Field Validation Error Messages', () => {
  beforeEach(() => {
    cy.visit('http://localhost:3000/form');
    cy.get('form').should('be.visible');
  });

  it('should display specific validation error for invalid email field', () => {
    cy.get('input[name="email"]').type('invalid-email');
    cy.get('button[type="submit"]').click();

    cy.get('[data-testid="email-error"]')
      .should('be.visible')
      .and('contain', 'Please enter a valid email address');

    cy.get('[data-testid="email-error"]')
      .should('have.class', 'error-message');
  });

  it('should display specific validation error for required name field', () => {
    cy.get('input[name="name"]').focus().blur();
    cy.get('button[type="submit"]').click();

    cy.get('[data-testid="name-error"]')
      .should('be.visible')
      .and('contain', 'Name is required');

    cy.get('input[name="name"]')
      .should('have.attr', 'aria-invalid', 'true');
  });

  it('should display specific validation error for password field with insufficient length', () => {
    cy.get('input[name="password"]').type('123');
    cy.get('button[type="submit"]').click();

    cy.get('[data-testid="password-error"]')
      .should('be.visible')
      .and('contain', 'Password must be at least 8 characters');
  });

  it('should display specific validation error for mismatched password confirmation', () => {
    cy.get('input[name="password"]').type('ValidPassword123');
    cy.get('input[name="confirmPassword"]').type('DifferentPassword123');
    cy.get('button[type="submit"]').click();

    cy.get('[data-testid="confirmPassword-error"]')
      .should('be.visible')
      .and('contain', 'Passwords do not match');
  });

  it('should display specific validation error for invalid phone number format', () => {
    cy.get('input[name="phone"]').type('12345');
    cy.get('button[type="submit"]').click();

    cy.get('[data-testid="phone-error"]')
      .should('be.visible')
      .and('contain', 'Phone number must be in format (XXX) XXX-XXXX');
  });

  it('should clear validation error when field is corrected', () => {
    cy.get('input[name="email"]').type('invalid-email');
    cy.get('button[type="submit"]').click();

    cy.get('[data-testid="email-error"]')
      .should('be.visible');

    cy.get('input[name="email"]').clear().type('valid@email.com');
    cy.get('input[name="email"]').blur();

    cy.get('[data-testid="email-error"]')
      .should('not.exist');
  });

  it('should display multiple validation errors simultaneously for multiple invalid fields', () => {
    cy.get('input[name="name"]').focus().blur();
    cy.get('input[name="email"]').type('invalid');
    cy.get('input[name="password"]').type('123');
    cy.get('button[type="submit"]').click();

    cy.get('[data-testid="name-error"]')
      .should('be.visible')
      .and('contain', 'Name is required');

    cy.get('[data-testid="email-error"]')
      .should('be.visible')
      .and('contain', 'Please enter a valid email address');

    cy.get('[data-testid="password-error"]')
      .should('be.visible')
      .and('contain', 'Password must be at least 8 characters');
  });

  it('should display validation error for special characters in name field', () => {
    cy.get('input[name="name"]').type('John@#$%Doe');
    cy.get('button[type="submit"]').click();

    cy.get('[data-testid="name-error"]')
      .should('be.visible')
      .and('contain', 'Name can only contain letters and spaces');
  });

  it('should display validation error for empty required fields on form submission', () => {
    cy.get('button[type="submit"]').click();

    cy.get('[data-testid="name-error"]')
      .should('be.visible');

    cy.get('[data-testid="email-error"]')
      .should('be.visible');

    cy.get('[data-testid="password-error"]')
      .should('be.visible');
  });

  it('should persist validation errors when navigating away and returning to form', () => {
    cy.get('input[name="email"]').type('invalid-email');
    cy.get('button[type="submit"]').click();

    cy.get('[data-testid="email-error"]')
      .should('be.visible');

    cy.visit('http://localhost:3000/home');
    cy.visit('http://localhost:3000/form');

    cy.get('[data-testid="email-error"]')
      .should('not.exist');
  });
});
